import React, { useEffect } from "react";
import "./LoginPage.css";
import Logo from "../../components/Img/Logo.jpeg";
import { useNavigate } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { LogIn, selectUser } from "../../store/slices/UserSlice";
import main from "../../components/Img/main.mp4";
const LoginPage = () => {

  const navigate = useNavigate();
  const dispatch = useDispatch()

  const login = async () => {
    // Шаг 1: Получить CSRF-cookie от Laravel Sanctum
    await fetch('http://localhost:8000/sanctum/csrf-cookie', {
      credentials: 'include',
    });
  
    // Шаг 2: Отправить логин-запрос
    const response = await fetch('http://localhost:8000/api/login', {
      method: 'POST',
      credentials: 'include', // для cookie
      headers: {
        'Content-Type': 'application/json',
        Accept: 'application/json',
      },
      body: JSON.stringify({
        email: 'test@example.com',   // <-- заменишь на данные из формы
        password: 'password',        // <-- тоже заменишь на свои данные
      }),
    });
  
    if (response.ok) {
      const user = await response.json();
      console.log('Вход успешен:', user);
      return user; // возвращаем пользователя в React
    } else {
      console.log('Ошибка входа');
      return null;
    }
  };
  return (
    <div className="main">
      <div className="overplay"></div>

      <video src={main} autoPlay loop muted />
      <div className="LoginPage">
        <div className="Header">
          <img className="img" src={Logo} alt="Logo" />
        </div>
        <div className="LoginWindow">
          <form onSubmit={(e) => handlerSubmit(e)}>
            <input className="LoginInput" type="text" placeholder="Login" />
            <input
              className="LoginInput"
              type="password"
              placeholder="Password"
            />
            <button className="LoginButton">Enter</button>
            <p>If you dont have account </p>
            <button
              className="CreateAccount"
              onClick={() => {
                navigate("/");
              }}
            >
              Create new Account
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default LoginPage;
